 function render(){handleDepth();let vals=oreValue(),mult=1+s.upgrades.cart*.15; $('coins').textContent=compact(s.coins);$('rate').textContent=rate().toFixed(rate()%1?1:0);$('lifetime').textContent=compact(s.lifetime);$('depth').textContent=s.depth;$('depthName').textContent=levelForDepth(s.depth);$('biome').textContent=biomeForDepth(s.depth);$('power').textContent=pickPower();$('clickYield').textContent=pickPower();$('critText').textContent=`${Math.round(critChance()*100)}% critical`;$('copper').textContent=compact(s.ore.copper);$('iron').textContent=compact(s.ore.iron);$('gold').textContent=compact(s.ore.gold);$('copperVal').textContent=compact(vals.copper*mult);$('ironVal').textContent=compact(vals.iron*mult);$('goldVal').textContent=compact(vals.gold*mult);$('sellValue').textContent=compact(sellTotal());$('sellAllValue').textContent=compact(sellTotal());$('shiftNum').textContent=String(s.shift).padStart(2,'0');let goal=depthThreshold(s.depth);$('depthProgressText').textContent=`${compact(s.depthOre)} / ${compact(goal)} ore`;$('depthProgress').style.width=Math.min(100,s.depthOre/goal*100)+'%';let m=s.depth<10?{title:'Reach the iron seam',desc:'Dig down to depth 10 m',reward:'+25 ⛃<br>bonus'}:s.depth<25?{title:'Find crystal hollows',desc:'Dig down to depth 25 m',reward:'+100 ⛃<br>bonus'}:s.depth<50?{title:'Break into the Deep Dark',desc:'Dig down to depth 50 m',reward:'+100 ⛃<br>bonus'}:{title:'How deep can you go?',desc:'Keep digging for bigger rewards',reward:'∞<br>depth'};$('milestoneTitle').textContent=m.title;$('milestoneDesc').textContent=m.desc;$('milestoneReward').innerHTML=m.reward;renderUpgrades()}
