+$('resetButton').onclick=()=> $('modal').classList.add('show');$('cancelReset').onclick=()=> $('modal').classList.remove('show');$('confirmReset').onclick=()=>{localStorage.removeItem(SAVE_KEY);location.reload()};$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').classList.remove('show')};
 document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));renderUpgrades()});
 document.addEventListener('keydown',e=>{if(e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();mine()}});
 let elapsed=Math.min(8*60*60,Math.max(0,(Date.now()-(s.last||Date.now()))/1000));if(elapsed>3&&rate()>0){let earned=Math.floor(rate()*elapsed);for(let i=0;i<earned;i++)s.ore[oreType()]++;s.lifetime+=earned;s.depthOre+=earned;s.coins+=0;setTimeout(()=>showToast(`Welcome back! Your crew mined ${compact(earned)} ore.`),500)}
