 function addOre(amount,manual=false){let bonus=manual&&Math.random()<critChance();let n=amount*(bonus?2:1);for(let i=0;i<n;i++)s.ore[oreType()]++;s.lifetime+=n;s.depthOre+=n;return{n,bonus}}
+function addBulk(n){if(n<=0)return;let pg=s.depth>=25?.2:0,pi=s.depth>=25?.23:s.depth>=10?.43:0;let g=Math.floor(n*pg),ir=Math.floor(n*pi);s.ore.gold+=g;s.ore.iron+=ir;s.ore.copper+=n-g-ir;s.lifetime+=n;s.depthOre+=n}
 function mine(){let res=addOre(pickPower(),true);const miner=$('miner');miner.classList.add('hit');setTimeout(()=>miner.classList.remove('hit'),130);floatOre(res.n,res.bonus);spawnChips();render();save()}
